from cyclopts import App

app = App(name="myapp")


@app.command
def add(a: int, b: int) -> int:
    """Add two integers."""
    return a + b


@app.command
def sub(a: int, b: int) -> int:
    """Subtract two integers."""
    return a - b


if __name__ == "__main__":
    tokens = ["add", "2", "3"]

    # parse_args resolves the command and binds arguments but does NOT invoke it.
    command, bound, ignored = app.parse_args(tokens, exit_on_error=False)

    print(f"Command function name: {command.__name__}")
    print(f"Bound arguments: {dict(bound.arguments)}")
